import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * TIER-02: what `contract/openapi.json` (generated by `npm run contract:build`)
 * says about the publishing gate, which is what the app's types are generated
 * from. The 402 body must be typed on every route that can answer it, and the
 * draft routes must be there.
 */

type Schema = {
  $ref?: string;
  allOf?: Schema[];
  nullable?: boolean;
  type?: string;
  enum?: string[];
  items?: Schema;
  required?: string[];
  properties?: Record<string, Schema>;
};
type Operation = {
  responses?: Record<
    string,
    { content?: Record<string, { schema?: Schema }>; description?: string }
  >;
};
type Contract = {
  paths: Record<string, Record<string, Operation>>;
  components: { schemas: Record<string, Schema> };
};

const contract = JSON.parse(
  readFileSync(join(__dirname, '../../../contract/openapi.json'), 'utf8'),
) as Contract;
const schemas = contract.components.schemas;

/** The routes that carry @GatesPublishing(), as OpenAPI writes them. */
const GATED: [string, string][] = [
  ['/api/hub/content', 'post'],
  ['/api/hub/content/{id}', 'patch'],
  ['/api/hub/content/{id}/resubmit', 'post'],
  ['/api/hub/uploads/presign', 'post'],
  ['/api/hub/product-drafts/{id}/publish', 'post'],
];

describe('the publishing gate contract (TIER-02)', () => {
  it.each(GATED)(
    '%s %s answers 402 with the typed tier-gate body',
    (path, method) => {
      const response = contract.paths[path]?.[method]?.responses?.['402'];
      expect(response).toBeDefined();
      expect(response?.description).toContain('tier_required');
      expect(response?.description).toContain('product_limit_reached');
      const schema = response?.content?.['application/json']?.schema;
      expect(schema?.$ref).toBe('#/components/schemas/TierGateErrorEnvelope');
    },
  );

  it('the 402 body is the one error envelope with a flat reason', () => {
    const envelope = schemas.TierGateErrorEnvelope;
    expect(Object.keys(envelope.properties ?? {}).sort()).toEqual(
      ['data', 'message', 'reason', 'statusCode'].sort(),
    );
    const reason = schemas.TierGateReasonDto;
    expect(reason.properties?.code.enum).toEqual([
      'tier_required',
      'product_limit_reached',
    ]);
    expect(reason.required).toEqual(
      expect.arrayContaining([
        'code',
        'message',
        'tierState',
        'productsUsed',
        'productsAllowed',
      ]),
    );
    // The offers are the plan's own types, not a second copy of them.
    expect(reason.properties?.tiers.items?.$ref).toBe(
      '#/components/schemas/PlanTierView',
    );
    expect(reason.properties?.productsUsed.type).toBe('integer');
    expect(reason.properties?.productsAllowed.type).toBe('integer');
  });

  it('GET /me/tier answers productsUsed as a whole number, always there', () => {
    const view = schemas.MyTierView;
    expect(view.properties?.productsUsed.type).toBe('integer');
    expect(view.required).toContain('productsUsed');
  });

  it('serves the draft routes', () => {
    expect(contract.paths['/api/hub/product-drafts']?.post).toBeDefined();
    expect(contract.paths['/api/hub/product-drafts']?.get).toBeDefined();
    const one = contract.paths['/api/hub/product-drafts/{id}'];
    expect(one?.get).toBeDefined();
    expect(one?.patch).toBeDefined();
    expect(one?.delete).toBeDefined();
    expect(
      contract.paths['/api/hub/product-drafts/{id}/publish']?.post,
    ).toBeDefined();
  });

  it('a draft says what publishing still needs, and may be missing every detail but a title', () => {
    const draft = schemas.ProductDraftView;
    expect(draft.required).toEqual(
      expect.arrayContaining(['id', 'title', 'missing', 'createdAt']),
    );
    expect(draft.properties?.missing.type).toBe('array');
    expect(draft.properties?.contentType.nullable).toBe(true);
    expect(draft.properties?.price.nullable).toBe(true);
  });
});
